{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01Bw5EXKZ9dYTmYk71SBK4eB","type":"tool_result","content":"{\"result\":\"{\\\"success\\\": true, \\\"data\\\": {\\\"stdout\\\": \\\"\\\\\\\"\\\\\\\"\\\\\\\"\\\\nA3: SDF Gradient-Guided Action Refinement via openpi train_loop hooks.\\\\n\\\\nExtends A1 (SDF auxiliary task) with gradient-guided action refinement:\\\\nuses dSDF/d(suffix features) to compute a \\\\\\\"collision-safe\\\\\\\" action target\\\\nand trains the model to output it directly.\\\\n\\\\nTwo-phase training:\\\\n  Phase 1 (0 -> warmup_phase_steps): Freeze backbone + LoRA. Train SDF decoder +\\\\n      EE extractor only (~658K params). SDF must be accurate before refinement.\\\\n  Phase 2 (warmup_phase_steps -> end): Unfreeze LoRA (~33.5M). Enable gradient\\\\n      refinement. Train with full loss:\\\\n      Loss = action_loss + lambda_sdf * sdf_loss + lambda_ee * ee_loss + lambda_refine * refine_loss\\\\n\\\\nKey difference from A1:\\\\n  - A1: SDF is an auxiliary loss that improves feature quality\\\\n  - A3: SDF gradient explicitly shifts action predictions away from collision\\\\n\\\\nDependencies:\\\\n  - openpi train_pytorch.py (TrainHooks, train_loop)\\\\n  - colliforce/sdf_decoder.py (SDFDecoder, compute_sdf_loss)\\\\n  - colliforce/ee_extractor.py (EEPositionExtractor)\\\\n  - colliforce/sdf_gradient_refiner.py (SDFGradientRefiner)\\\\n  - SDF GT npz (query_points + sdf_values)\\\\n\\\\nUsage:\\\\n    CUDA_VISIBLE_DEVICES=3 python scripts/train_a3_hook.py --scene spatial_bowl --dry_run\\\\n    CUDA_VISIBLE_DEVICES=3 python scripts/train_a3_hook.py --scene spatial_bowl --seed 0\\\\n\\\\\\\"\\\\\\\"\\\\\\\"\\\\nimport argparse\\\\nimport logging\\\\nimport os\\\\nimport sys\\\\n\\\\nimport numpy as np\\\\nimport torch\\\\nimport torch.nn as nn\\\\nimport torch.nn.functional as F\\\\n\\\\nsys.path.insert(0, os.path.join(os.path.dirname(__file__), \\\\\\\"..\\\\\\\", \\\\\\\"openpi\\\\\\\"))\\\\nsys.path.insert(0, os.path.join(os.path.dirname(__file__), \\\\\\\"..\\\\\\\", \\\\\\\"openpi\\\\\\\", \\\\\\\"src\\\\\\\"))\\\\nsys.path.insert(0, os.path.join(os.path.dirname(__file__), \\\\\\\"..\\\\\\\"))\\\\n\\\\nos.environ[\\\\\\\"HF_LEROBOT_HOME\\\\\\\"] = \\\\\\\"/root/autodl-tmp/colliforce_data\\\\\\\"\\\\n\\\\nimport openpi.models.pi0_config as pi0_config\\\\nimport openpi.training.config as _config\\\\nfrom openpi.training.optimizer import CosineDecaySchedule\\\\nfrom colliforce.sdf_decoder import SDFDecoder, compute_sdf_loss\\\\nfrom colliforce.ee_extractor import EEPositionExtractor\\\\nfrom colliforce.sdf_gradient_refiner import SDFGradientRefiner\\\\nfrom scripts.train_pytorch import TrainHooks, train_loop\\\\n\\\\n\\\\nSCENE_CONFIG = {\\\\n    \\\\\\\"spatial_bowl\\\\\\\": {\\\\n        \\\\\\\"description\\\\\\\": \\\\\\\"SafeLIBERO Spatial: bowl between plate and ramekin\\\\\\\",\\\\n        \\\\\\\"data_subdir\\\\\\\": \\\\\\\"safelibero_spatial\\\\\\\",\\\\n        \\\\\\\"sdf_gt\\\\\\\": \\\\\\\"/root/colliforce-vla/data/sdf_gt_spatial_bowl.npz\\\\\\\",\\\\n    },\\\\n    \\\\\\\"object_pudding\\\\\\\": {\\\\n        \\\\\\\"description\\\\\\\": \\\\\\\"SafeLIBERO Object: pick chocolate pudding into basket\\\\\\\",\\\\n        \\\\\\\"data_subdir\\\\\\\": \\\\\\\"safelibero_object\\\\\\\",\\\\n        \\\\\\\"sdf_gt\\\\\\\": \\\\\\\"/root/colliforce-vla/data/sdf_gt_object_chocolate.npz\\\\\\\",\\\\n    },\\\\n}\\\\n\\\\nCHECKPOINT_BASE = \\\\\\\"/root/autodl-tmp/checkpoints\\\\\\\"\\\\nDATA_BASE = \\\\\\\"/root/autodl-tmp/colliforce_data\\\\\\\"\\\\nWEIGHTS_BASE = \\\\\\\"/root/autodl-tmp/openpi_weights\\\\\\\"\\\\n\\\\n\\\\n# ---------------------------------------------------------------------------\\\\n# Manual LoRA -- identical to A1 (PEFT not installed)\\\\n# ---------------------------------------------------------------------------\\\\n\\\\nclass LoRALinear(nn.Module):\\\\n    \\\\\\\"\\\\\\\"\\\\\\\"Drop-in nn.Linear replacement with low-rank adapters.\\\\n    Base weight frozen; only lora_A/lora_B are trainable.\\\\n    \\\\\\\"\\\\\\\"\\\\\\\"\\\\n\\\\n    def __init__(self, base: nn.Linear, rank: int = 16, alpha: float = 16.0):\\\\n        super().__init__()\\\\n        self.base = base\\\\n        for p in self.base.parameters():\\\\n            p.requires_grad = False\\\\n        in_f, out_f = base.in_features, base.out_features\\\\n        dev = base.weight.device\\\\n        self.lora_A = nn.Parameter(torch.randn(in_f, rank, device=dev) * 0.01)\\\\n        self.lora_B = nn.Parameter(torch.zeros(rank, out_f, device=dev))\\\\n        self.scaling = alpha / rank\\\\n\\\\n    @property\\\\n    def weight(self):\\\\n        return self.base.weight\\\\n\\\\n    @property\\\\n    def bias(self):\\\\n        return self.base.bias\\\\n\\\\n    def forward(self, x):\\\\n        base_out = self.base(x.to(self.base.weight.dtype))\\\\n        lora_out = (x.float() @ self.lora_A.float() @ self.lora_B.float()) * self.scaling\\\\n        return base_out + lora_out.to(base_out.dtype)\\\\n\\\\n\\\\ndef _replace_linear(parent: nn.\\\\n\\\\n... [截断: 输出过长，省略 12167 字符] ...\\\\n\\\\n       os.path.join(step_dir, \\\\\\\"aux_metadata.pt\\\\\\\"))\\\\n        logging.info(\\\\\\\"Saved aux modules + LoRA at step %d\\\\\\\", global_step)\\\\n\\\\n    def on_cleanup(self):\\\\n        if self.hook_handle is not None:\\\\n            self.hook_handle.remove()\\\\n        for h in getattr(self, '_lora_grad_hooks', []):\\\\n            h.remove()\\\\n\\\\n\\\\n# ---------------------------------------------------------------------------\\\\n# Config builder\\\\n# ---------------------------------------------------------------------------\\\\n\\\\ndef parse_args():\\\\n    p = argparse.ArgumentParser(description=\\\\\\\"A3: pi0 + SDF gradient refinement via hooks\\\\\\\")\\\\n    p.add_argument(\\\\\\\"--scene\\\\\\\", type=str, required=True, choices=list(SCENE_CONFIG.keys()))\\\\n    p.add_argument(\\\\\\\"--seed\\\\\\\", type=int, default=0)\\\\